using System.Linq;
using System.Collections.Generic;
using Autodesk.Revit.DB;

var doc = Document;
// setup: a floor plan with no view template (filters editable)
var view = new FilteredElementCollector(doc).OfClass(typeof(ViewPlan)).Cast<ViewPlan>()
    .First(v => !v.IsTemplate && v.ViewType == ViewType.FloorPlan && v.ViewTemplateId == ElementId.InvalidElementId);
var cats = new List<ElementId> { new ElementId(BuiltInCategory.OST_Furniture) };

// a filter rule's parameter must be one that is FILTERABLE for the chosen categories
var filterable = ParameterFilterUtilities.GetFilterableParametersInCommon(doc, cats);
var comments = new ElementId(BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS);
var paramId = filterable.Contains(comments) ? comments : filterable.First();
var rule = ParameterFilterRuleFactory.CreateHasValueParameterRule(paramId);
var ef = new ElementParameterFilter(rule);

ElementId filterId = null;
// step 1: create a category filter on a filterable parameter and hide it in the view
Connector.WithTransaction(doc, () => {
    var pfe = ParameterFilterElement.Create(doc, "MCP Hide Furniture " + System.Guid.NewGuid().ToString("N").Substring(0, 4), cats, ef);
    filterId = pfe.Id;
    view.SetFilterVisibility(filterId, false);   // auto-adds the filter, then hides matched elements
});

// verify: the filter is on the view and its visibility is off
var onView = view.GetFilters().Contains(filterId);
var vis = view.GetFilterVisibility(filterId);
return new { filterId = filterId.ToString(), viewName = view.Name, ruleParameterId = paramId.ToString(), filterOnView = onView, filterVisibility = vis, filterableParamCount = filterable.Count };
